The three errors came from string literals in step inputs. `'accept'`, `'withdraw'` and `'offer'` were widened to `string` before the command's input type could narrow them. The input mapper's return is typed `NoInfer<In>`, and `In` has no constraint, so TypeScript drops the literal type while it infers.

I fixed this in the scenario, not the surface. The fix that would remove the widening in the surface is a `const` type parameter on `step`. That would also turn array literals in other scenarios' step inputs into readonly tuples, which may break them.

In the scenario, the message kind is now a named zod enum, `messageKind`. Each step reads its value from `messageKind.enum.<name>`, which already has the literal type, so nothing is widened. There are no casts, and the scenario still expresses the same things.

=== FILE: scenarios/08-hostile-lifecycles.ts ===
import { z } from 'zod';
import { H } from 'harness-dsl';
import { claudeCode } from 'harness-dsl/claude-code';
import { anthropic } from 'harness-dsl/anthropic';
import { sqlite } from 'harness-dsl/sqlite';
import { http } from 'harness-dsl/http';
import { manual } from 'harness-dsl/supply';
import { runners } from 'harness-dsl/runners';
import { policies } from 'harness-dsl/policies';
import { observers } from 'harness-dsl/observers';

const api = H.account('anthropic-api', anthropic.api({ apiKey: H.env('ANTHROPIC_API_KEY') }));
const haiku = H.model('claude-haiku-4-5').pricing(anthropic.pricing());
const sonnet = H.model('claude-sonnet-4-5').pricing(anthropic.pricing());
const pool = H.pool('api', [api]).serves(haiku, sonnet).policy(policies.soonestReset());

const local = runners.local({ name: 'local', slots: 4 }).env({ ANALYTICS_TOKEN: H.env('ANALYTICS_TOKEN') });

const due = H.state('due').pending();
const sampling = H.state('sampling').active();
const measuring = H.state('measuring').waiting();
const aWon = H.state('a-won').terminal('neutral');
const bWon = H.state('b-won').terminal('neutral');
const inconclusive = H.state('inconclusive').terminal('neutral');

const experimentSchema = z.object({ name: z.string(), metric: z.string() });
const experiment = H.work('Experiment').schema(experimentSchema).states(due, sampling, measuring, aWon, bWon, inconclusive);

const collectSample = H.command('collect-sample')
  .input(z.object({ experiment: z.string(), metric: z.string() }))
  .output(z.object({ a: z.number(), b: z.number() }))
  .runner(local)
  .effect('repeatable')
  .run(async (input, ctx) => {
    const result = await ctx.exec(['abctl', 'sample', input.experiment, input.metric]);
    const [a, b] = result.stdout.trim().split(' ').map(Number);
    return { a: a ?? 0, b: b ?? 0 };
  });

const decideExperiment = H.command('decide-experiment')
  .input(z.object({ experiment: z.string() }))
  .output(z.object({ winner: z.enum(['A', 'B', 'none']) }))
  .runner(local)
  .effect('repeatable')
  .run(async (input, ctx) => {
    const result = await ctx.exec(['abctl', 'verdict', input.experiment]);
    const verdict = result.stdout.trim();
    return { winner: verdict === 'A' ? 'A' : verdict === 'B' ? 'B' : 'none' };
  });

const experimentHour = H.flow('experiment-hour')
  .input(experimentSchema)
  .step('sample', collectSample, s => ({ experiment: s.input.name, metric: s.input.metric }))
  .when((_, ctx) => ctx.now.getTime() - ctx.unit.created.getTime() < 14 * 86_400_000, f => f.exit('measured'))
  .step('verdict', decideExperiment, s => ({ experiment: s.input.name }))
  .when(s => s.verdict.winner === 'A', f => f.exit('aWins'))
  .when(s => s.verdict.winner === 'B', f => f.exit('bWins'))
  .exit('inconclusive');

const experiments = H.lane('experiments')
  .of(experiment)
  .from(manual('operator-experiments'))
  .store(sqlite.store('./lifecycles/experiments.sqlite'))
  .handle(experimentHour, {
    exits: { measured: measuring, aWins: aWon, bWins: bWon, inconclusive },
    retry: { retries: 2, backoff: { initial: '1m', factor: 2 }, exhausted: measuring },
  });

const reviewDue = H.state('review-due').pending();
const reviewing = H.state('reviewing').active();
const customer = H.state('customer').waiting();
const suspended = H.state('suspended').waiting();
const churned = H.state('churned').terminal('neutral');

const tenancySchema = z.object({
  customer: z.string(),
  plan: z.string(),
  billing: z.enum(['active', 'suspended', 'churned']),
});
const tenancy = H.work('Tenancy').schema(tenancySchema).states(reviewDue, reviewing, customer, suspended, churned);

const usageReview = H.command('usage-review')
  .input(z.object({ customer: z.string() }))
  .output(z.object({ report: z.string() }))
  .runner(local)
  .effect('repeatable')
  .run(async (input, ctx) => {
    const result = await ctx.exec(['usage-report', '--customer', input.customer, '--last', '30d']);
    return { report: result.stdout };
  });

const accountManagerRole = H.role('account-manager').prompt('Summarise a customer month for an upsell decision.').intents(['read']);
const summarySkill = H.skill('tenancy-summary')
  .input(z.object({ customer: z.string(), plan: z.string(), usage: z.string() }))
  .output(z.object({ summary: z.string() }))
  .prompt(i => `Customer ${i.customer} on ${i.plan}. Usage:\n${i.usage}`);
const summarizer = H.seat('tenancy-summarizer').role(accountManagerRole).skill(summarySkill).models(haiku);

const upsellDecision = H.halt('upsell-decision')
  .context(z.object({ customer: z.string(), summary: z.string() }))
  .decision(z.object({ upsell: z.boolean(), plan: z.string() }))
  .ask(c => `Upsell ${c.customer}?\n${c.summary}`);

const openUpsellTask = H.command('open-upsell-task')
  .input(z.object({ customer: z.string(), plan: z.string() }))
  .output(z.object({ task: z.string() }))
  .runner(local)
  .effect('unrepeatable')
  .detect(async (input, ctx) => {
    const found = await ctx.exec(['crm', 'find-task', '--customer', input.customer, '--plan', input.plan]);
    return found.code === 0 && found.stdout.trim() ? { task: found.stdout.trim() } : undefined;
  })
  .run(async (input, ctx) => {
    const created = await ctx.exec(['crm', 'create-task', '--customer', input.customer, '--plan', input.plan]);
    return { task: created.stdout.trim() };
  });

const monthlyReview = H.flow('monthly-tenancy-review')
  .input(tenancySchema)
  .step('usage', usageReview, s => ({ customer: s.input.customer }))
  .step('summary', summarizer, s => ({ customer: s.input.customer, plan: s.input.plan, usage: s.usage.report }))
  .halt('upsell', upsellDecision, s => ({ customer: s.input.customer, summary: s.summary.summary }))
  .when(s => s.upsell.upsell, f => f.step('proposal', openUpsellTask, s => ({ customer: s.input.customer, plan: s.upsell.plan })))
  .exit('reviewed');

const tenancies = H.lane('tenancies')
  .of(tenancy)
  .from(
    http.webhook({
      name: 'billing-events',
      path: '/billing',
      port: H.slot.port(0),
      secret: H.env('BILLING_WEBHOOK_SECRET'),
      body: tenancySchema,
      key: b => b.customer,
      data: b => b,
      mode: 'upsert',
    }),
  )
  .store(sqlite.store('./lifecycles/tenancies.sqlite'))
  .handle(monthlyReview, {
    exits: { reviewed: customer },
    retry: { retries: 2, backoff: { initial: '1h', factor: 2 }, exhausted: customer },
  });

const negotiating = H.state('negotiating').pending();
const drafting = H.state('drafting').active();
const awaitingVendor = H.state('awaiting-vendor').waiting();
const stalled = H.state('stalled').waiting();
const agreed = H.state('agreed').terminal('success');
const walkedAwayByUs = H.state('walked-away-by-us').terminal('neutral');
const walkedAwayByThem = H.state('walked-away-by-them').terminal('neutral');
const expired = H.state('expired').terminal('neutral');

const negotiationSchema = z.object({
  negotiationId: z.string(),
  vendor: z.string(),
  item: z.string(),
  ceilingUsd: z.number(),
  expiresAt: z.string(),
  lastVendorMessage: z.string(),
  vendorStatus: z.enum(['negotiating', 'accepted', 'walkedAway']),
});
const negotiation = H.work('Negotiation')
  .schema(negotiationSchema)
  .states(negotiating, drafting, awaitingVendor, stalled, agreed, walkedAwayByUs, walkedAwayByThem, expired);

const negotiatorRole = H.role('negotiator').prompt('Draft the next procurement offer within the ceiling.').intents(['read']);
const offerSkill = H.skill('next-offer')
  .input(z.object({ vendor: z.string(), item: z.string(), ceilingUsd: z.number(), lastVendorMessage: z.string() }))
  .output(z.object({ action: z.enum(['offer', 'accept', 'walkAway']), offerUsd: z.number(), message: z.string() }))
  .prompt(i => `Vendor ${i.vendor} for ${i.item}, ceiling $${i.ceilingUsd}. They said: ${i.lastVendorMessage}`);
const negotiator = H.seat('negotiator').role(negotiatorRole).skill(offerSkill).models(sonnet);

const confirmWalkAway = H.halt('confirm-walk-away')
  .context(z.object({ vendor: z.string(), reason: z.string() }))
  .decision(z.object({ confirmed: z.boolean() }))
  .ask(c => `Walk away from ${c.vendor}? ${c.reason}`);

const messageKind = z.enum(['offer', 'accept', 'withdraw']);

const vendorMessage = H.command('vendor-message')
  .input(z.object({ negotiationId: z.string(), kind: messageKind, message: z.string(), offerUsd: z.number() }))
  .output(z.object({ messageId: z.string() }))
  .runner(local)
  .effect('unrepeatable')
  .detect(async (input, ctx) => {
    const found = await ctx.exec(['procure', 'find-message', input.negotiationId, ctx.attempt]);
    return found.code === 0 && found.stdout.trim() ? { messageId: found.stdout.trim() } : undefined;
  })
  .run(async (input, ctx) => {
    const sent = await ctx.exec(['procure', 'send', input.negotiationId, input.kind, String(input.offerUsd), '--ref', ctx.attempt], { stdin: input.message });
    return { messageId: sent.stdout.trim() };
  });

const negotiationRound = H.flow('negotiation-round')
  .input(negotiationSchema)
  .step('draft', negotiator, s => ({
    vendor: s.input.vendor,
    item: s.input.item,
    ceilingUsd: s.input.ceilingUsd,
    lastVendorMessage: s.input.lastVendorMessage,
  }))
  .when(s => s.draft.action === 'accept', f =>
    f
      .step('accept', vendorMessage, s => ({ negotiationId: s.input.negotiationId, kind: messageKind.enum.accept, message: s.draft.message, offerUsd: s.draft.offerUsd }))
      .exit('agreed'),
  )
  .when(s => s.draft.action === 'walkAway', f =>
    f
      .halt('confirmWalkAway', confirmWalkAway, s => ({ vendor: s.input.vendor, reason: s.draft.message }))
      .when(s => s.confirmWalkAway.confirmed, g =>
        g
          .step('withdraw', vendorMessage, s => ({ negotiationId: s.input.negotiationId, kind: messageKind.enum.withdraw, message: s.draft.message, offerUsd: 0 }))
          .exit('walkedAway'),
      ),
  )
  .step('offer', vendorMessage, s => ({ negotiationId: s.input.negotiationId, kind: messageKind.enum.offer, message: s.draft.message, offerUsd: s.draft.offerUsd }))
  .exit('offered');

const negotiations = H.lane('negotiations')
  .of(negotiation)
  .from(
    manual('operator-negotiations'),
    http.webhook({
      name: 'vendor-replies',
      path: '/vendor-replies',
      port: H.slot.port(0),
      secret: H.env('VENDOR_WEBHOOK_SECRET'),
      body: negotiationSchema,
      key: b => b.negotiationId,
      data: b => b,
      mode: 'update',
    }),
  )
  .store(sqlite.store('./lifecycles/negotiations.sqlite'))
  .handle(negotiationRound, {
    exits: { agreed, walkedAway: walkedAwayByUs, offered: awaitingVendor },
    retry: { retries: 2, backoff: { initial: '10m', factor: 2 }, exhausted: stalled },
  })
  .wip(3);

const vendorUpdates = H.events.updates(negotiations);

const triggers = [
  H.trigger('experiment-hourly').on(H.time.every('0 * * * *')).do(experiments.move({ state: measuring }, due)),
  H.trigger('tenancy-monthly').on(H.time.every('0 9 1 * *')).do(tenancies.move({ state: customer }, reviewDue)),
  H.trigger('tenancy-suspended')
    .on(H.events.updates(tenancies).where(e => e.unit.data.billing === 'suspended' && e.previous.billing !== 'suspended'))
    .do(tenancies.move(e => e.unit.key, suspended)),
  H.trigger('tenancy-reinstated')
    .on(H.events.updates(tenancies).where(e => e.unit.data.billing === 'active' && e.previous.billing === 'suspended'))
    .do(tenancies.move(e => e.unit.key, customer)),
  H.trigger('tenancy-churned')
    .on(H.events.updates(tenancies).where(e => e.unit.data.billing === 'churned'))
    .do(tenancies.move(e => e.unit.key, churned)),
  H.trigger('vendor-replied')
    .on(vendorUpdates.where(e => e.unit.data.vendorStatus === 'negotiating' && e.unit.state === awaitingVendor.name))
    .do(negotiations.move(e => e.unit.key, negotiating)),
  H.trigger('vendor-accepted')
    .on(vendorUpdates.where(e => e.unit.data.vendorStatus === 'accepted'))
    .do(negotiations.move(e => e.unit.key, agreed)),
  H.trigger('vendor-walked-away')
    .on(vendorUpdates.where(e => e.unit.data.vendorStatus === 'walkedAway'))
    .do(negotiations.move(e => e.unit.key, walkedAwayByThem)),
  H.trigger('negotiation-expiry')
    .on(H.time.at(negotiations, d => new Date(d.expiresAt)))
    .do(negotiations.move(e => e.unit.key, expired)),
];

export const inconclusiveRate = H.metric('experiment-inconclusive-rate', H.events.transitions(experiments, { terminal: true }))
  .rate(e => e.to === inconclusive.name)
  .window('90d');

export const experimentOutcomes = H.metric('experiment-outcomes', H.events.transitions(experiments, { terminal: true }))
  .count()
  .by('state')
  .window('90d');

const order = H.policy.units('tenancies-negotiations-experiments', ({ candidates, metrics }) => {
  const inconclusiveReading = metrics.read(inconclusiveRate);
  const experimentsUnreliable = inconclusiveReading.samples >= 10 && (inconclusiveReading.value ?? 0) > 0.5;
  const rank = (lane: string) =>
    lane === tenancies.name ? 0 : lane === negotiations.name ? 1 : experimentsUnreliable ? 3 : 2;
  return [...candidates].sort((a, b) => rank(a.lane) - rank(b.lane) || a.queuedAt.getTime() - b.queuedAt.getTime());
});

export const harness = H.harness('lifecycles')
  .ledger(sqlite.ledger('./lifecycles/ledger.sqlite'))
  .pools(pool)
  .lanes(experiments, tenancies, negotiations)
  .triggers(...triggers)
  .scheduler(order)
  .grants(
    H.grant(
      claudeCode.client({ name: 'operator' }),
      H.ops.work.read,
      H.ops.work.write,
      H.ops.resolve(upsellDecision),
      H.ops.resolve(confirmWalkAway),
      H.ops.telemetry.read,
      H.ops.attempts.manage,
    ),
  )
  .observe(observers.board({ path: './lifecycles/BOARD.md' }), observers.telemetry({ path: './lifecycles/TELEMETRY.md' }));

export const running = harness.start();
=== END ===

Both errors had one cause. The halt's decision type was inferred through `DecisionOf<Hl>` at the same time as the callback that returns a decision. So TypeScript inferred the callback's return before it had fixed the decision type, and widened `'approved'` and `'approve'` to `string`.

The fix is in `h.d.ts` only. `Flow.halt` and `H.policy.halt` now take the decision type `D` straight from the `Halt<string, D>` argument. The callbacks (`skip`, `clock.decide`, `decide`) receive it as `NoInfer<D>`. Literal decisions now check against the halt's own schema.

No types were loosened and no scenario changed.

=== FILE: h.d.ts ===
declare module 'harness-dsl' {
  import { z } from 'zod';
  import {
    Named,
    EnvRef,
    PortRef,
    Verdict,
    State,
    UnitView,
    WorkRef,
    Metrics,
    Policy,
    AccountState,
    Account,
    Model,
    RunnerBackend,
    Workspace,
    Supplier,
    Store,
    MemoryStore,
    Ledger,
    Client,
    Observer,
    Scope,
    MetricRef,
    Measure,
    Window,
    JobPoll,
    LeaseMode,
    DecisionSource,
  } from 'harness-dsl/kernel';
  export * from 'harness-dsl/kernel';

  export type Schema<T> = z.ZodType<T>;
  export type Empty = { readonly [K in never]: never };

  export interface KindShape<A, S extends State> extends WorkRef<S['name']> {
    readonly entity: 'kind';
    readonly _types?: { readonly attrs: A; readonly states: S };
  }

  export interface Kind<N extends string, A, S extends State> extends KindShape<A, S> {
    readonly name: N;
    attributes<A2 extends object>(schema: Schema<A2>): Kind<N, A2, S>;
    states<S2 extends State[]>(...states: S2): Kind<N, A, S2[number]>;
    key(identity: (attrs: A) => string): Kind<N, A, S>;
    initial(state: S): Kind<N, A, S>;
    onAttemptFailed(state: S): Kind<N, A, S>;
    onCancelled(state: S): Kind<N, A, S>;
  }

  export interface Signal<N extends string = string, P = unknown> extends Named {
    readonly name: N;
    readonly _payload?: P;
    payload<P2>(schema: Schema<P2>): Signal<N, P2>;
  }

  export interface Halt<N extends string = string, D = unknown> extends Named {
    readonly entity: 'halt';
    readonly name: N;
    readonly _decision?: D;
  }

  export type DecisionOf<Hl> = Hl extends Halt<string, infer D> ? D : never;

  export interface Resource extends Named {
    readonly entity: 'resource';
  }

  export interface Lease {
    readonly resource: Resource;
    readonly mode: LeaseMode;
  }

  export interface Executable<I, O> extends Named {
    readonly _io?: { readonly in: (input: I) => void; readonly out: O };
  }

  export interface Job<I, O> extends Executable<I, O> {
    readonly entity: 'job';
  }

  export interface CommandResult {
    readonly exitCode: number;
    readonly stdout: string;
    readonly stderr: string;
  }

  export interface Command<I, O> extends Executable<I, O> {
    input<I2>(schema: Schema<I2>): Command<I2, O>;
    argv(argv: readonly string[] | ((input: I) => readonly string[])): Command<I, O>;
    output<O2>(schema: Schema<O2>): Command<I, O2>;
    runner(runner: Runner | ((input: I) => Runner)): Command<I, O>;
    acceptExitCodes(...exitCodes: number[]): Command<I, O>;
  }

  export interface Runner extends Named {
    readonly backend: RunnerBackend;
    slots(count: number): Runner;
    preflight(check: Executable<void, unknown>): Runner;
  }

  export type Intent = 'read' | 'edit' | 'run' | 'search' | 'browse' | 'halt' | 'record';

  export interface Role extends Named {
    intents(...intents: Intent[]): Role;
    instructions(text: string): Role;
  }

  export interface AgentTask {
    readonly task: string;
    readonly resources?: readonly string[];
    readonly skills?: readonly string[];
  }

  export interface Guard { readonly guard: 'lease' | 'beforeStop' }

  export interface Agent<O> extends Executable<AgentTask, O> {
    role(role: Role): Agent<O>;
    model(model: Model | ModelPolicy): Agent<O>;
    pool(pool: Pool): Agent<O>;
    output<O2>(schema: Schema<O2>): Agent<O2>;
    workspace(workspace: Workspace): Agent<O>;
    guards(...guards: Guard[]): Agent<O>;
    batch(): Executable<readonly AgentTask[], readonly O[]>;
  }

  export interface PolicyCtx {
    readonly kind: WorkRef;
    readonly metrics: Metrics;
  }

  export interface ModelPolicy extends Policy<PolicyCtx, Model> {
    readonly candidates: readonly Model[];
  }

  export interface HaltPolicyCtx<A> {
    readonly unit: UnitView<A>;
    readonly metrics: Metrics;
  }

  export interface HaltPolicy<A, D> extends Policy<HaltPolicyCtx<A>, D | undefined> {
    readonly entity: 'haltPolicy';
    readonly halt: Halt<string, D>;
  }

  export interface AccountPolicyCtx {
    readonly candidates: readonly AccountState[];
    readonly now: Date;
  }

  export type AccountPolicy = Policy<AccountPolicyCtx, AccountState | undefined>;

  export interface Pool extends Named {
    accounts(...accounts: Account[]): Pool;
    share(account: Account, fraction: number): Pool;
    drain(policy: AccountPolicy): Pool;
    fallback(account: Account): Pool;
  }

  export interface MemoryKind extends Named {
    readonly trust: 'experience' | 'taste';
  }

  export interface Journal extends Named {
    readonly entity: 'journal';
    store(store: MemoryStore): Journal;
    recall(recall: { readonly by: 'specificity' | 'similarity'; readonly limit: number }): Journal;
    readBy(...roles: Role[]): Journal;
    recordedBy(...roles: Role[]): Journal;
  }

  export interface MemoryDraft {
    readonly text: string;
    readonly when?: Scope;
    readonly status?: 'candidate' | 'active';
  }

  export interface Retry {
    readonly maxAttempts: number;
    readonly backoff: 'fixed' | 'exponential';
    readonly initialDelayMs: number;
  }

  export interface StepOptions<I> {
    readonly retry?: Retry;
    readonly afterCrash?: 'rerun' | 'park' | 'askDriver';
    readonly alreadyDone?: Executable<I, boolean>;
  }

  export interface FlowCtx<In, P, St> {
    readonly unit: UnitView<In>;
    readonly params: P;
    readonly steps: St;
    readonly metrics: Metrics;
    readonly iteration: number;
    readonly now: Date;
  }

  export interface HaltOptions<In, P, St, D> {
    readonly ask: (ctx: FlowCtx<In, P, St>) => string;
    readonly skip?: HaltPolicy<In, D> | ((ctx: FlowCtx<In, P, St>) => D | undefined);
    readonly clock?: {
      readonly afterMinutes: number;
      readonly decide: (ctx: FlowCtx<In, P, St>) => D;
    };
  }

  export interface ChildResult {
    readonly unitId: string;
    readonly state: string;
    readonly verdict: Verdict;
  }

  export interface Flow<In, P, St, X extends string, N extends string> extends Named {
    readonly _types?: {
      readonly input: (attrs: In) => void;
      readonly params: (params: P) => P;
      readonly steps: St;
      readonly exits: X;
      readonly stepNames: N;
    };
    input<In2>(schema: Schema<In2>): Flow<In2, P, St, X, N>;
    params<P2>(schema: Schema<P2>): Flow<In, P2, St, X, N>;
    step<M extends string, O>(
      name: M,
      exec: Executable<void, O>,
      options?: StepOptions<void>,
    ): Flow<In, P, St & { readonly [K in M]: O }, X, N | M>;
    step<M extends string, I, O>(
      name: M,
      exec: Executable<I, O>,
      input: (ctx: FlowCtx<In, P, St>) => I,
      options?: StepOptions<I>,
    ): Flow<In, P, St & { readonly [K in M]: O }, X, N | M>;
    halt<M extends string, D>(
      name: M,
      halt: Halt<string, D>,
      options: HaltOptions<In, P, St, NoInfer<D>>,
    ): Flow<In, P, St & { readonly [K in M]: D }, X, N | M>;
    halt<M extends string, D>(
      name: M,
      halt: {
        readonly ask: (ctx: FlowCtx<In, P, St>) => string;
        readonly decision: Schema<D>;
        readonly skip?: (ctx: FlowCtx<In, P, St>) => NoInfer<D> | undefined;
      },
    ): Flow<In, P, St & { readonly [K in M]: D }, X, N | M>;
    wait<M extends string>(
      name: M,
      wait: { readonly ms: number },
    ): Flow<In, P, St & { readonly [K in M]: Date }, X, N | M>;
    spawn<M extends string, A2>(
      name: M,
      lane: LaneShape<A2, State, unknown>,
      children: (ctx: FlowCtx<In, P, St>) => readonly A2[],
    ): Flow<In, P, St & { readonly [K in M]: readonly ChildResult[] }, X, N | M>;
    loop<M extends string, St2, X2 extends string, N2 extends string>(
      name: M,
      body: (flow: Flow<In, P, St, X, N>) => Flow<In, P, St2, X2, N2>,
      bounds: {
        readonly max?: number | ((ctx: FlowCtx<In, P, St>) => number);
        readonly counts?: (ctx: FlowCtx<In, P, St2>) => boolean;
        readonly until?: (ctx: FlowCtx<In, P, St2>) => boolean;
      },
    ): Flow<In, P, St2, X2, N2 | M>;
    exit<M extends string>(
      name: M,
      when?: (ctx: FlowCtx<In, P, St>) => boolean,
    ): Flow<In, P, St, X | M, N>;
  }

  export interface LaneShape<A, S extends State, St> extends WorkRef<S['name']> {
    readonly entity: 'lane';
    readonly _types?: { readonly attrs: A; readonly states: S; readonly steps: St };
  }

  export type LaneRef = LaneShape<unknown, State, unknown>;

  export type ActiveState<S extends State> = Extract<S, State<string, 'active'>>;
  export type WaitingState<S extends State> = Extract<S, State<string, 'waiting'>>;

  export interface HandlerMap<S extends State, X extends string, N extends string> {
    readonly exits: { readonly [K in X]: S };
    readonly during?: { readonly [K in N]?: ActiveState<S> };
  }

  export type InputFits<A, I> = [A] extends [I] ? unknown : { readonly flowInputDoesNotFitKind: I };

  export interface Reaction<A, S extends State, N extends string, P, St> {
    readonly update?: (attrs: A, payload: P) => A;
    readonly restart?: N;
    readonly enter?: S;
    readonly resolve?: { readonly [K in keyof St & N]?: (payload: P, attrs: A) => St[K] };
  }

  export interface Route { readonly route: 'create' | 'signal' | 'skip' }

  export interface Router<A, SN extends string> {
    create(attrs: A): Route;
    signal<P>(
      signal: Signal<string, P>,
      target: string | ((unit: UnitView<A, SN>) => boolean),
      payload: P,
    ): Route;
    skip(): Route;
  }

  export interface OperatorSupplier extends Named { readonly operator: true }

  export interface Lane<A, S extends State, St, N extends string> extends LaneShape<A, S, St> {
    readonly _types?: { readonly attrs: A; readonly states: S; readonly steps: St; readonly stepNames: N };
    supply(supplier: OperatorSupplier): Lane<A, S, St, N>;
    supply<E>(
      supplier: Supplier<E>,
      route: (event: E, to: Router<A, S['name']>) => Route | readonly Route[],
    ): Lane<A, S, St, N>;
    store(store: Store): Lane<A, S, St, N>;
    handler<I, St2, X extends string, N2 extends string>(
      flow: Flow<I, void, St2, X, N2>,
      map: HandlerMap<S, X, N2> & InputFits<A, I>,
    ): Lane<A, S, St2, N2>;
    handler<I, P, St2, X extends string, N2 extends string>(
      flow: Flow<I, P, St2, X, N2>,
      map: HandlerMap<S, X, N2> & { readonly params: P } & InputFits<A, I>,
    ): Lane<A, S, St2, N2>;
    retry(policy: Retry & { readonly exhausted: S }): Lane<A, S, St, N>;
    lease(claim: (unit: UnitView<A, S['name']>) => Lease): Lane<A, S, St, N>;
    order(
      sequence: (unit: UnitView<A, S['name']>) => string,
      options: { readonly onEarlierFailed: WaitingState<S> },
    ): Lane<A, S, St, N>;
    on<P>(signal: Signal<string, P>, reaction: Reaction<A, S, N, P, St>): Lane<A, S, St, N>;
    ceiling(ceiling: { readonly maxUsd: number; readonly onExceed: 'halt' | 'fail' }): Lane<A, S, St, N>;
  }

  export interface Tick { readonly at: Date }
  export type Weekday = 'mon' | 'tue' | 'wed' | 'thu' | 'fri' | 'sat' | 'sun';

  export interface Clock extends Supplier<Tick> {
    every(interval: { readonly minutes: number }): Clock;
    at(time: string, options?: { readonly on?: Weekday | number; readonly tz?: string }): Clock;
  }

  export interface TransitionEvent<A, SN extends string = string> {
    readonly unit: UnitView<A, SN>;
    readonly to: SN;
    readonly attempt?: { readonly durationMs: number };
    readonly at: Date;
  }

  export interface PatternEvent<A, SN extends string = string> extends TransitionEvent<A, SN> {
    readonly group: string;
    readonly streak: number;
  }

  export interface TimerEvent<A, SN extends string = string> {
    readonly unit: UnitView<A, SN>;
    readonly at: Date;
  }

  export interface StepEvent<A, O, St> {
    readonly unit: UnitView<A>;
    readonly ok: boolean;
    readonly output?: O;
    readonly outputs: { readonly [K in keyof St]?: St[K] };
    readonly models: { readonly [K in keyof St]?: string };
    readonly durationMs: number;
    readonly at: Date;
  }

  export interface InvocationEvent {
    readonly model?: string;
    readonly ok: boolean;
    readonly costUsd: number;
  }

  export interface HaltedEvent<A> {
    readonly unit: UnitView<A>;
    readonly halt: string;
    readonly ask: string;
    readonly haltedAt: Date;
    readonly at: Date;
  }

  export interface DecisionEvent<A, D> {
    readonly unit: UnitView<A>;
    readonly decision: D;
    readonly resolvedBy: DecisionSource;
    readonly client?: string;
    readonly waitedMs: number;
    readonly at: Date;
  }

  export interface LeaseEvent {
    readonly unit: UnitView<unknown>;
    readonly resource: Resource;
    readonly mode: LeaseMode;
    readonly waitedMs: number;
    readonly at: Date;
  }

  export type Threshold = { readonly below: number } | { readonly above: number };

  export interface CrossingEvent {
    readonly group: string;
    readonly edge: 'entered' | 'exited';
    readonly value: number;
    readonly samples: number;
  }

  export interface Source<E> extends Named { readonly _event?: E }

  export type StateMatch<S extends State> = S | readonly S[];

  export interface TriggerRef extends Named {
    readonly entity: 'trigger';
  }

  export interface Trigger<E> extends TriggerRef {
    on<E2>(source: Source<E2>): Trigger<E2>;
    create<A>(lane: LaneShape<A, State, unknown>, attrs: (event: E) => A | undefined): Trigger<E>;
    signal<P>(
      signal: Signal<string, P>,
      lane: LaneRef,
      target: (event: E) => { readonly key: string; readonly payload: P } | undefined,
    ): Trigger<E>;
    record(journal: Journal, item: (event: E) => MemoryDraft | undefined): Trigger<E>;
    pause(lane: LaneRef, reason: (event: E) => string | undefined): Trigger<E>;
    resume(lane: LaneRef, reason: (event: E) => string | undefined): Trigger<E>;
    run<I>(exec: Executable<I, unknown>, input: (event: E) => I | undefined): Trigger<E>;
  }

  export interface Sample { readonly group: string; readonly hit: boolean }
  export interface Amount { readonly group: string; readonly amount: number }

  export interface MetricDraft<E> extends Named {
    samples(extract: (event: E) => readonly Sample[]): MetricRef<'rate'>;
    amounts(extract: (event: E) => readonly Amount[]): MetricRef<'total'>;
  }

  export interface AdmitCtx<A> {
    readonly unit: UnitView<A>;
    readonly active: (lane: LaneRef) => number;
    readonly pending: (lane: LaneRef) => number;
    readonly metrics: Metrics;
  }

  export interface Scheduler extends Named {
    priority(...lanes: LaneRef[]): Scheduler;
    wip(lane: LaneRef, maxActive: number): Scheduler;
    boost(lane: LaneRef, aging: { readonly afterMinutes: number }): Scheduler;
    rank<A>(lane: LaneShape<A, State, unknown>, key: (unit: UnitView<A>) => number): Scheduler;
    admit<A>(lane: LaneShape<A, State, unknown>, gate: (ctx: AdmitCtx<A>) => boolean): Scheduler;
  }

  export interface Operation<I, O> extends Named {
    readonly _io?: { readonly in: (input: I) => void; readonly out: O };
  }

  export type Grant = Operation<never, unknown>;

  export interface Harness extends Named {
    ledger(ledger: Ledger): Harness;
    lanes(...lanes: LaneRef[]): Harness;
    journals(...journals: Journal[]): Harness;
    triggers(...triggers: TriggerRef[]): Harness;
    metrics(...metrics: MetricRef<Measure>[]): Harness;
    scheduler(scheduler: Scheduler): Harness;
    clients(...clients: Client[]): Harness;
    observers(...observers: Observer[]): Harness;
    start(): Promise<void>;
  }

  export const H: {
    env(name: string): EnvRef;
    readonly slot: { port(slot: number): PortRef };
    nextTime(at: string, options: { readonly after: Date; readonly tz?: string }): Date;

    kind<N extends string>(name: N): Kind<N, Empty, never>;
    state<N extends string, P extends 'pending' | 'active' | 'waiting'>(name: N, position: P): State<N, P>;
    terminal<N extends string>(name: N, verdict: Verdict): State<N, 'terminal'>;
    signal<N extends string>(name: N): Signal<N, Empty>;
    readonly cancel: Signal<'cancel', { readonly reason?: string }>;
    halt<N extends string, D>(name: N, decision: Schema<D>): Halt<N, D>;
    resource(name: string): Resource;
    role(name: string): Role;
    memory(name: string, trust: 'experience' | 'taste'): MemoryKind;

    command(name: string): Command<void, CommandResult>;
    job<I, S, O>(
      name: string,
      job: {
        readonly submit: Executable<I, S>;
        readonly collect: Executable<S, JobPoll<O>>;
        readonly every: { readonly minutes: number };
      },
    ): Job<I, O>;
    agent(name: string): Agent<string>;
    pool(name: string): Pool;
    readonly guard: {
      lease(): Guard;
      beforeStop(check: Executable<void, unknown>): Guard;
    };
    readonly policy: {
      model(name: string, candidates: readonly Model[], choose: (ctx: PolicyCtx) => Model): ModelPolicy;
      account(name: string, choose: (ctx: AccountPolicyCtx) => AccountState | undefined): AccountPolicy;
      halt<A, S extends State, D>(
        name: string,
        kind: KindShape<A, S>,
        halt: Halt<string, D>,
        decide: (ctx: HaltPolicyCtx<A>) => NoInfer<D> | undefined,
      ): HaltPolicy<A, D>;
    };

    flow(name: string): Flow<unknown, void, Empty, never, never>;
    lane<A, S extends State>(name: string, kind: KindShape<A, S>): Lane<A, S, Empty, never>;
    journal(name: string, of: MemoryKind): Journal;
    clock(name: string): Clock;
    readonly operator: OperatorSupplier;

    trigger(name: string): Trigger<never>;
    readonly when: {
      transition<A, S extends State, St>(
        lane: LaneShape<A, S, St>,
        filter?: {
          readonly to?: StateMatch<NoInfer<S>>;
          readonly if?: (event: TransitionEvent<A, S['name']>) => boolean;
        },
      ): Source<TransitionEvent<A, S['name']>>;
      pattern<A, S extends State, St>(
        lane: LaneShape<A, S, St>,
        pattern: {
          readonly to: StateMatch<NoInfer<S>>;
          readonly consecutive: number;
          readonly per: (unit: UnitView<A, S['name']>) => string;
        },
      ): Source<PatternEvent<A, S['name']>>;
      timer<A, S extends State, St>(
        lane: LaneShape<A, S, St>,
        timer: { readonly at: (unit: UnitView<A, S['name']>) => Date | undefined },
      ): Source<TimerEvent<A, S['name']>>;
      step<A, S extends State, St, M extends keyof St & string>(
        lane: LaneShape<A, S, St>,
        step: M,
        filter?: { readonly if?: (event: StepEvent<A, St[M], St>) => boolean },
      ): Source<StepEvent<A, St[M], St>>;
      invocation(filter: { readonly lanes: readonly LaneRef[] }): Source<InvocationEvent>;
      crossing(
        metric: MetricRef<'rate'>,
        crossing: {
          readonly window: Window;
          readonly minSamples: number;
          readonly enter: Threshold;
          readonly exit: Threshold;
          readonly groups?: (group: string) => boolean;
        },
      ): Source<CrossingEvent>;
      halted<A, S extends State>(
        halt: Halt,
        filter: { readonly kind: KindShape<A, S>; readonly afterMinutes: number },
      ): Source<HaltedEvent<A>>;
      decided<A, S extends State, D>(
        halt: Halt<string, D>,
        filter: { readonly kind: KindShape<A, S> },
      ): Source<DecisionEvent<A, D>>;
      leased(...lanes: LaneRef[]): Source<LeaseEvent>;
    };
    metric<E>(name: string, source: Source<E>): MetricDraft<E>;
    scheduler(name: string): Scheduler;

    operation<O>(name: string, exec: Executable<void, O>): Operation<void, O>;
    readonly ops: {
      readonly workRead: Grant;
      readonly workCreate: Grant;
      readonly workUpdate: Grant;
      readonly workCancel: Grant;
      readonly workSignal: Grant;
      readonly blockersResolve: Grant;
      readonly attemptsRecover: Grant;
      readonly lanesPause: Grant;
      readonly memoryRead: Grant;
      readonly memoryWrite: Grant;
      readonly memoryCurate: Grant;
      readonly telemetryRead: Grant;
      readonly accountsRead: Grant;
      readonly accountsShare: Grant;
      resolve(halt: Halt): Grant;
    };
    harness(name: string): Harness;
  };
}

